window.blogDetail = {"blogId":1527420803,"blogType":0,"pubTime":"2018-05-27 19:33","cate":"个人日记","cateHex":"b8f6c8cbc8d5bcc7","title":"我读红楼梦（34）第29回 享福人福深还祷福，痴情女情重愈斟情——珍惜是福","commentNum":0,"effect1":1024,"effect2":524294,"ar":0,"block":0,"inproc":false,"appeal":0,"abstract":"佛说，世间有八苦，生老病死，怨憎会，爱别离，求不得，五取蕴。在下总觉得，在这八苦当中，唯有求不得苦是完完全全可以避免的，生老病死是人之常态，怨憎会，爱别离两者，是命运使然。一个在一生当中没有爱过，也没有恨过的人，就不能称之为完整的人，爱和恨，都是人生的一种独特的体验。它往往是一种特殊的彻悟的途径。至于我们每天所听到的，所看到的，所触碰到的，主要是来自于我们对外界的感知。如果一个人隔绝了对外界的感知...","artype":1,"arUins":"","blogid":1527420803,"voteids":0,"pubtime":1527420803,"replynum":0,"category":"个人日记","effect":1024,"exblogtype":0,"sus_flag":false,"friendrelation":[],"lp_type":0,"lp_id":0,"lp_style":0,"lp_flag":0,"orguin":619774944,"orgblogid":1527420803,"mention_uins":[],"attach":[],"comments":[],"html":"","custom_title":"我读红楼梦（34）第29回 享福人福深还祷福，痴情女情重愈斟情——珍惜是福","custom_html":"","uniKey":"http://user.qzone.qq.com/619774944/blog/1527420803"}